"""Raw probe/theory statistics and explicitly bounded operator conclusions."""
import csv,json
from pathlib import Path
import numpy as np
from .transformer_block_gpu import sha,save_json,write_csv
OUT=Path('results/thrml_spw/range_localization')
def main():
    p=json.loads((OUT/'protocol.json').read_text());m=json.loads((OUT/'native_manifest.json').read_text());assert json.loads((OUT/'analytic_evidence_audit.json').read_text())['passed'] and json.loads((OUT/'native_evidence_audit.json').read_text())['passed'];raw={};summary=[];ratio=[];total=0
    with (OUT/'analytic_operator_metrics.csv').open() as f:analytic={(int(v['stage']),int(v['group'])):v for v in csv.DictReader(f)}
    with (OUT/'native_probe_metrics.csv').open() as f:source_rows=list(csv.DictReader(f))
    for case in m['cases']:
        cond=next(c for c in p['native_conditions'] if c['name']==case['condition']);stage,seed=case['stage'],case['seed'];meta=json.loads(Path(case['metadata']).read_text());y,target=np.load(case['output']),np.load(case['target']);mse=float(np.mean((y.astype(float)-target)**2));rr=next(v for v in source_rows if v['condition']==case['condition'] and int(v['stage'])==stage and int(v['seed'])==seed);np.testing.assert_allclose(float(rr['observed_target_MSE']),mse,rtol=1e-12,atol=1e-14);np.testing.assert_allclose(meta['observed_target_MSE'],mse,rtol=1e-12,atol=1e-14);raw[case['condition'],stage,seed]=mse;updates=cond['samples']*p['control_artifacts'][str(cond['group'])][stage]['weights'];assert meta['observed_node_updates']==int(rr['observed_node_updates'])==updates;total+=updates
    assert len(raw)==360 and total==m['native_observed_updates']==434865438720
    means=np.load(OUT/'mean_model_tokens.npz');truth=np.load(OUT/'validation_tokens.npz')['tokens'][:,1:]
    with (OUT/'mean_model_metrics.csv').open() as f:
        for row in csv.DictReader(f):
            key='FP32' if row['condition']=='FP32' else row['condition'].replace('programmed_mean_','');ce=float(means[key+'_nll'].astype(float).mean());accuracy=float(np.mean(means[key+'_predictions']==truth))
            for name,value in [('cross_entropy',ce),('perplexity',float(np.exp(ce))),('token_accuracy',accuracy)]:np.testing.assert_allclose(float(row[name]),value,rtol=1e-12,atol=1e-14)

    for cond in p['native_conditions']:
        for stage in range(24):
            values=np.array([raw[cond['name'],stage,s] for s in range(5)]);expected=float(analytic[stage,cond['group']][f'predicted_target_MSE_T{cond["samples"]}']);mean=float(values.mean());r=mean/expected;summary.append({'condition':cond['name'],'stage':stage,'group':cond['group'],'samples':cond['samples'],'mean_target_MSE':mean,'seed_std':float(values.std(ddof=1)),'approx_seed_normal95_margin':float(1.96*values.std(ddof=1)/np.sqrt(5)),'predicted_target_MSE':expected,'observed_over_prediction':r,'within_predeclared_20percent':bool(.8<=r<=1.2)})
    for label,left,right in [('fine_halfT_vs_coarse1024','g16_T512','g128_T1024'),('fine_vs_coarse_sameT512','g16_T512','g128_T512'),('coarse512_vs_coarse1024','g128_T512','g128_T1024')]:
        logs=np.array([np.mean([np.log(raw[left,k,s]/raw[right,k,s]) for k in range(24)]) for s in range(5)]);center=float(logs.mean());margin=float(1.96*logs.std(ddof=1)/np.sqrt(5));ratio.append({'contrast':label,'numerator':left,'denominator':right,'geometric_MSE_ratio':float(np.exp(center)),'approx_seed_normal95_low':float(np.exp(center-margin)),'approx_seed_normal95_high':float(np.exp(center+margin)),'MC_seed_log_ratios':logs.tolist(),'scope':'Geometric mean across fixed24 layers per independent MCseed; normal5seed sensitivity, not architecture/generalization guarantee. Ratios compare raw error to same FP32-math targets, not full neural task quality.'})
    write_csv(OUT/'probe_summary.csv',summary);save_json(OUT/'paired_operator_ratios.json',ratio);audit=json.loads((OUT/'native_evidence_audit.json').read_text());payload={str(g):{'parameter_payload_bytes':sum(c['parameter_payload_bytes'] for c in p['control_artifacts'][str(g)]),'group_flag_bytes':sum(c['group_flag_bytes'] for c in p['control_artifacts'][str(g)]),'bits_per_converted_weight':8*sum(c['parameter_payload_bytes'] for c in p['control_artifacts'][str(g)])/42467328} for g in p['groups']}
    r={'passed':all(v['within_predeclared_20percent'] for v in summary),'raw_native_cases_recomputed':360,'perlayer_condition_summaries':72,'all_predeclared_theory_checks_within20percent':all(v['within_predeclared_20percent'] for v in summary),'min_observed_over_prediction':min(v['observed_over_prediction'] for v in summary),'max_observed_over_prediction':max(v['observed_over_prediction'] for v in summary),'native_production_observed_updates':total,'independent_output_and_frequency_replay_updates':audit['native_replay_observed_updates'],'total_executed_native_updates':total+audit['native_replay_observed_updates'],'converted_logical_free_nodes_each_design':42467328,'payload':payload,'operator_primary':ratio[0],'full_stochastic_neural_forward_runs':0,'heldout_test_runs':0,'source_sha256':sha(__file__),'scope':'Independent raw MSE and fixed theory gate summary after original-model/range/public-native audits. Practical20% theory check is not a statistical coverage claim. Probe precision gain is conditional on extra range metadata; no full stochastic NN or physical-system improvement established.'};save_json(OUT/'evidence_audit.json',r);print(json.dumps(r,indent=2))
if __name__=='__main__':main()
